MOD = 10**9 + 7

def mod_inverse(a, m):
    return pow(a, m - 2, m)

def binomial_coefficient(n, k, m):
    if k > n:
        return 0
    num = factorial(n) % m
    den = (factorial(k) * factorial(n - k)) % m
    return num * mod_inverse(den, m) % m

