from math import factorial

MOD = 10**9 + 7

def count_ways(n, k):
    if n == 1:
        return k % MOD

    def inv(x):
        return pow(x, MOD - 2, MOD)

    def choose(n, k):
        if k > n:
            return 0
        return factorial(n) * inv(factorial(k)) * inv(factorial(n - k)) % MOD

    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(i + 1):
            dp[i][j] = (dp[i - 1][j] * (i - j + 1) + dp[i - 1][j - 1] * j) % MOD

    result = 0
    for i in range(n + 1):
        result += dp[n][i] * choose(k, i) * choose(k, i) * (-1)**i
        result %= MOD

    return result

